scwin.unitTest = function() {
    // debugger;
    // Init test
    WebSquare.wUnit.start();
    // Test step 1: 1. 샘플파일을 실행 및 콘솔을 열고 treeView의 이미지를 클릭한다. 
    // - 1. Run the sample file and open the console and click the image of the treeView.
    // Verify 1: 1. 콘솔창에 "onImageClick" 이벤트가 1번 정상적으로 발생한다. (이전에는 주석처리가 되지 않아 스튜디오에 노출되지않아 노출되도록 수정)
    // 1. The 'onImageClick' event normally occurs once in the console window. (Previously unannotated and exposed to the studio. Not to be exposed)
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('tv1_icon_2').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('tv1_icon_4').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    // Run test
    WebSquare.wUnit.run();
    // Stop test
    WebSquare.wUnit.stop();
}
